import { NextResponse, type NextRequest } from "next/server";
import { requireMember, requireWriter } from "@/lib/auth";
import { requirePaidOrg } from "@/lib/entitlement";
import { routeError } from "@/lib/route";
import { ingestCoi, MAX_COI_BYTES } from "@/lib/covercheck/ingest";
import { queueChase } from "@/lib/covercheck/chase";
import { adminSupabase } from "@/lib/supabase/admin";

export const runtime = "nodejs";
export const maxDuration = 120;

/** Upload a certificate: store it, read it, check it, queue any chase drafts. */
export async function POST(req: NextRequest) {
  try {
    const session = await requireMember();
    requireWriter(session);
    // ⛔ THE PAID CHECK RUNS BEFORE THE FILE IS EVEN READ (2026-09-05). `ingestCoi` calls
    // the extraction model, and until today this route checked membership and role and
    // nothing else, so an org on a lapsed "free" plan could spend ANTHROPIC_API_KEY on
    // every upload. Isaiah, 2026-09-05: nothing consumes the paid LLM keys except a paying
    // customer's own usage. It throws UnpaidError, which routeError renders as a 402.
    await requirePaidOrg(session.orgId);

    const form = await req.formData();
    const file = form.get("file");
    const vendorId = form.get("vendorId");

    if (!(file instanceof File)) {
      return NextResponse.json({ error: "Attach a certificate file." }, { status: 400 });
    }
    if (typeof vendorId !== "string" || !vendorId) {
      return NextResponse.json({ error: "Pick the vendor this certificate belongs to." }, { status: 400 });
    }
    if (file.size > MAX_COI_BYTES) {
      return NextResponse.json({ error: "That file is larger than 20MB." }, { status: 413 });
    }

    const bytes = new Uint8Array(await file.arrayBuffer());
    const outcome = await ingestCoi({
      orgId: session.orgId,
      vendorId,
      userId: session.userId,
      bytes,
      mimeType: file.type || "application/pdf",
      filename: file.name,
    });

    // Queue a draft for anything that came back short. Drafts only — nothing
    // sends until a manager approves it.
    if (outcome.checks.length > 0) {
      const admin = adminSupabase();
      const { data: vendor } = await admin
        .from("cc_vendors")
        .select("name, agent_email")
        .eq("id", vendorId)
        .maybeSingle();

      for (const check of outcome.checks) {
        await queueChase({
          orgId: session.orgId,
          vendorId,
          communityId: check.communityId,
          coiId: outcome.coiId,
          vendorName: vendor?.name ?? "the vendor",
          communityName: check.communityName,
          agentEmail: vendor?.agent_email ?? null,
          result: check.result,
        });
      }
    }

    return NextResponse.json({
      coiId: outcome.coiId,
      status: outcome.status,
      detail: outcome.detail,
      checks: outcome.checks.map((c) => ({
        community: c.communityName,
        status: c.result.status,
        daysToExpiry: c.result.daysToExpiry,
        findings: c.result.findings,
      })),
    });
  } catch (err) {
    return routeError(err);
  }
}

